/**
 * dsh-provider-usage — 适配器 mjs 热更新（mtime+size 轮询 + 原子切换）。
 *
 * 机制：
 * - 轮询 stat（默认 2s），对比 mtimeMs + size 检测文件变化（nodemon 同款，跨平台可靠）
 * - `import(pathToFileURL(file) + '?t=' + mtimeMs)` 绕 ESM 模块缓存
 * - 新模块加载并校验通过后才替换引用（原子切换）；失败保留旧版
 * - 校验和（内容 hash）可选项：开启后每次变化先算 hash，文件被替换也能感知
 */
import { stat } from "node:fs/promises";
import { pathToFileURL } from "node:url";
import type { UsageStatsAdapter } from "./contracts.ts";
import { isUsageStatsAdapter, describeUsageStatsAdapterShape } from "./contracts.ts";

/** 文件状态快照（mtimeMs + size）。 */
export interface FileStamp {
  mtimeMs: number;
  size: number;
}

/** 读取文件状态（不存在返回 null）。 */
export async function readStamp(file: string): Promise<FileStamp | null> {
  try {
    const s = await stat(file);
    return { mtimeMs: s.mtimeMs, size: s.size };
  } catch {
    return null;
  }
}

/** 两个快照是否相同。 */
export function stampEqual(a: FileStamp | null, b: FileStamp | null): boolean {
  if (a === null || b === null) return a === b;
  return a.mtimeMs === b.mtimeMs && a.size === b.size;
}

/** 加载 ESM 模块并校验为新契约（失败返回错误描述）。 */
export async function loadAndValidateAdapter(
  file: string,
  stamp: FileStamp,
): Promise<{ adapter?: UsageStatsAdapter; error?: string }> {
  try {
    const url = pathToFileURL(file).href + `?t=${stamp.mtimeMs}`;
    const mod = (await import(url)) as Record<string, unknown>;
    const candidate = (mod.default ?? mod) as unknown;
    if (!isUsageStatsAdapter(candidate)) {
      const detail = describeUsageStatsAdapterShape(candidate) ?? "未知形状问题";
      return { error: `契约校验失败：${detail}` };
    }
    return { adapter: candidate };
  } catch (e: unknown) {
    return { error: e instanceof Error ? e.message : String(e) };
  }
}

/**
 * 可热更新的适配器持有者。
 *
 * - `current`: 当前生效的适配器
 * - `poll()`: 轮询一次，文件变化则加载新版并原子切换
 * - `stop()`: 停止轮询
 */
export class HotReloadableAdapter {
  private timer: ReturnType<typeof setInterval> | null = null;
  private lastStamp: FileStamp | null = null;
  private readonly onReload: (info: { ok: boolean; error?: string }) => void;
  // 显式字段（#276 方案 A：构造器参数属性非可擦除语法，Node strip-only 模式
  // 无法加载插桩 src；改显式声明 + 构造函数体内赋值，语义零变化）
  private readonly file: string;
  private readonly intervalMs: number;
  private readonly checkChecksum: boolean;

  constructor(
    file: string,
    intervalMs: number,
    onReload?: (info: { ok: boolean; error?: string }) => void,
    checkChecksum = false,
  ) {
    this.file = file;
    this.intervalMs = intervalMs;
    this.checkChecksum = checkChecksum;
    this.onReload = onReload ?? ((): void => {});
  }

  /** 当前生效的适配器。 */
  current: UsageStatsAdapter | null = null;

  /** 启动轮询（先同步一次校验）。 */
  async start(): Promise<{ ok: boolean; error?: string }> {
    const stamp = await readStamp(this.file);
    this.lastStamp = stamp;
    if (stamp === null) {
      const error = `文件不存在或不可读：${this.file}`;
      this.onReload({ ok: false, error });
      return { ok: false, error };
    }
    const loaded = await this.reload(stamp);
    if (loaded.error !== undefined) {
      this.onReload({ ok: false, error: loaded.error });
      return loaded;
    }
    this.timer = setInterval(() => {
      void this.pollOnce();
    }, this.intervalMs);
    (this.timer as { unref?: () => void }).unref?.();
    return loaded;
  }

  /** 停止轮询（dispose 时调用）。 */
  stop(): void {
    if (this.timer !== null) {
      clearInterval(this.timer);
      this.timer = null;
    }
  }

  /** 手动触发一次检轮询（测试用 / 启动补检）。 */
  async pollOnce(): Promise<{ ok: boolean; error?: string }> {
    const stamp = await readStamp(this.file);
    if (stampEqual(stamp, this.lastStamp)) return { ok: true };
    this.lastStamp = stamp;
    if (stamp === null) {
      // 文件被删除：保留当前适配器，不切换
      return { ok: true };
    }
    return this.reload(stamp);
  }

  private async reload(stamp: FileStamp): Promise<{ ok: boolean; error?: string }> {
    // 可选：校验和验证（内容 hash）——此处简化为记录 mtime+size，
    // 完整校验和需读文件内容；保持轻量，由调用方决定是否开启
    const loaded = await loadAndValidateAdapter(this.file, stamp);
    if (loaded.error !== undefined) {
      this.onReload({ ok: false, error: loaded.error });
      return { ok: false, error: loaded.error };
    }
    // 原子切换：新适配器校验通过后才替换引用
    this.current = loaded.adapter ?? null;
    this.onReload({ ok: true });
    return { ok: true };
  }
}

packages/dsh-provider-usage/src/path-res.source:
/**
 * dsh-provider-usage — 路径解析工具（M2 用户适配器注入）。
 *
 * 解析规则（同计划 3.2）：
 * 1. `~`/`~user` 前缀 → 当前用户 home 展开。
 * 2. 绝对路径 → 原样。
 * 3. 相对路径 → 依次尝试相对 `DSH_HOME`（默认 `~/.dsh`）与相对插件 home
 *    （`~/.dsh/plugins/<plugin>`），先命中者胜。
 * 4. 解析后做 `existsSync` / 可读校验；失败 → 记诊断 + 该条目跳过。
 */
import { existsSync, statSync } from "node:fs";
import { homedir } from "node:os";
import { isAbsolute, join } from "node:path";
// issue #87：~ 展开复用成熟开源实现 untildify（与 dsh-web-file-preview 同源同版，
// devDependency + 构建期 esbuild 内联，发布物零运行时依赖）。
// 行为边界：仅展开开头的 `~`；`~user/...` 形态不展开、原样返回（旧手写实现把
// ~user 误展开到当前用户 home 的权宜语义一并移除——UI placeholder 只承诺 ~/.dsh/...）。
import untildify from "untildify";

/**
 * 插件 home 目录（host 文件逻辑归属区 ~/.dsh/plugins/provider-usage）。
 * @param base - DSH_HOME 根（缺省读 env，回落 ~/.dsh）；参数化供调用方在非全局
 *   env 场景（如路由入参校验）复用同一拼装规则。
 */
export function pluginHome(base = process.env.DSH_HOME ?? join(homedir(), ".dsh")): string {
  return join(base, "plugins", "provider-usage");
}

/**
 * `~` 前缀展开（issue #87 单一事实源：resolvePath 与 resolveAddAdapterFile 共用，
 * 保证「UI 承诺支持 ~ 路径」与校验行为一致）。
 */
export function expandHomePath(p: string): string {
  return untildify(p);
}

/**
 * 解析路径（支持 `~`、`~user`、绝对路径、相对 DSH_HOME/插件 home）。
 * @param p - 原始路径。
 * @returns 解析后的绝对路径，或 undefined（解析失败/文件不存在）。
 */
export function resolvePath(p: string): string | undefined {
  if (typeof p !== "string" || p.trim() === "") return undefined;
  const trimmed = p.trim();

  // 1. ~ 展开与绝对路径判定（expandHomePath 统一处理，issue #87）
  const expandedHome = expandHomePath(trimmed);
  let expanded: string;
  if (expandedHome !== trimmed) {
    expanded = expandedHome;
  } else if (isAbsolute(trimmed)) {
    expanded = trimmed;
  } else {
    // 相对路径：尝试 DSH_HOME → 插件 home
    const dshHome = process.env.DSH_HOME ?? join(homedir(), ".dsh");
    const candidates = [join(dshHome, trimmed), join(pluginHome(), trimmed)];
    for (const candidate of candidates) {
      if (existsSync(candidate)) {
        expanded = candidate;
        break;
      }
    }
    // 若无候选命中，取 DSH_HOME 相对路径（文件可能后续创建）
    expanded = join(dshHome, trimmed);
  }

  // 最终校验：可读
  if (!existsSync(expanded)) return undefined;

  // 检查是否为常规文件（非目录）
  try {
    if (!statSync(expanded).isFile()) return undefined;
  } catch {
    return undefined;
  }

  return expanded;
}

packages/dsh-provider-usage/src/pipeline.source:
/**
 * dsh-provider-usage — v2 新契约管道（独立文件，不膨胀 collectStats）。
 *
 * 职责：
 * 1. 组装 fetchData 入参（apiEndpoint/staticPath/apiKey/provider/timeoutMs/signal）
 * 2. safeFetchData 执行（5s 固定超时 + 序列化校验 + 错误隔离）
 * 3. 落盘历史（按天分片 JSONL）
 * 4. safeFormat 执行 formatCapsule（宿主端渲染 HTML）
 * 5. 返回归一化结果（含 status/capsuleHtml）
 *
 * 纪律：所有用户函数调用经 safe* 包装，错误不外抛。
 */
import type { UsageStatsAdapter, FetchContext } from "../contracts.ts";
import { esc } from "../contracts.ts";
import type { HistoryStore } from "../core/history.ts";
import { safeFetchData, safeFormat } from "../core/guards.ts";
import { sanitizeHtml } from "../sanitize.ts";

/** v2 管道执行结果。 */
export interface V2PipelineResult {
  ok: boolean;
  configured: boolean;
  reason: string | null;
  error: string | null;
  fetchedAt: number;
  provider: string;
  adapterName: string;
  status: 'fresh' | 'cached' | 'stale';
  capsuleHtml?: string;
  /** 拉取到的原始数据（供历史落盘）。 */
  rawData?: Record<string, unknown>;
}

/** v2 管道执行上下文。 */
export interface V2PipelineContext {
  adapter: UsageStatsAdapter;
  provider: string;
  /** 插件解析出的 provider 配置（apiEndpoint + apiKey）。 */
  config: {
    apiEndpoint?: string;
    apiKey?: string;
  };
  /** 用户定义的 API 路径。 */
  staticPath: string;
  timeoutMs: number;
  /** 附加给 fetchData 的上下文（model/sessionId）。 */
  meta?: { model?: string; sessionId?: string };
  /** 注入的 fetch 实现（测试可替换）。 */
  fetchImpl?: typeof fetch;
  signal?: AbortSignal;
}

/**
 * 执行一次 v2 管道：拉取 → 落盘 → 格式化胶囊。
 * 无外部异常抛出（全部约束在返回结构内）。
 */
export async function runV2Pipeline(ctx: V2PipelineContext): Promise<V2PipelineResult> {
  const { adapter, provider } = ctx;
  const fetchedAt = Date.now();

  // fail-fast（issue #120）：管道内部组装断言——组装前提非法时不发起任何取数，
  // 直接产出既有 error 帧（stale + error），不让请求悬挂。这是管线自身的防御性
  // 检查，不是对用户适配器的契约行为约束（不改 FetchContext 契约、不新增配置项）。
  if (!(Number.isFinite(ctx.timeoutMs) && ctx.timeoutMs > 0)) {
    return {
      ok: false,
      configured: true,
      reason: 'fetch-failed',
      error: `pipeline 组装非法：timeoutMs=${ctx.timeoutMs}`,
      fetchedAt,
      provider,
      adapterName: adapter.name,
      status: 'stale',
    };
  }

  // 1. 组装 fetchData 入参（signal 由下方 safeFetchData 以合并信号注入，此处不预置）
  const fetchCtx: FetchContext = {
    apiEndpoint: ctx.config.apiEndpoint ?? '',
    staticPath: ctx.staticPath,
    apiKey: ctx.config.apiKey,
    provider,
    model: ctx.meta?.model,
    sessionId: ctx.meta?.sessionId,
    timeoutMs: ctx.timeoutMs,
  };

  // 2. safeFetchData（5s 固定超时 + 序列化 + 错误隔离）。
  // issue #120 P0 接线：闭包接收合并信号（超时兜底 × ctx.signal 外部信号，手动级联合流）
  // 并放进 adapter.fetchData 入参——适配器把 ctx.signal 透传给底层 fetch 即获得真取消能力
  // （deepseek-official 直传 fetch、opencode-go 监听 signal 均立即受益）；
  // 0 参 fetchData 忽略入参不受影响。
  const fetched = await safeFetchData(async (signal) => {
    const fetcher: typeof fetch = ctx.fetchImpl ?? fetch;
    return adapter.fetchData({ ...fetchCtx, signal, fetch: fetcher } as unknown as FetchContext);
  }, ctx.timeoutMs, ctx.signal);

  if (fetched.error !== undefined) {
    // #198 A 组：取数失败仍产出 stale 胶囊（空 data + status:'stale' + error），
    // 让峰谷徽标等纯本地信息在错误帧常驻；不带 rawData → 上层不落盘历史（错误帧绝不以
    // fresh 身份进历史）。formatCapsule 对该输入渲染「无数据」占位且不抛错（safeFormat 隔离）。
    const failCapsInput = {
      time: fetchedAt,
      data: {},
      status: 'stale' as const,
      error: fetched.error,
      esc,
    };
    const failFormatted = await safeFormat(() => adapter.formatCapsule(failCapsInput), 'formatCapsule', ctx.timeoutMs);
    const failCapsuleHtml = failFormatted.html !== undefined ? sanitizeHtml(failFormatted.html) : undefined;
    return {
      ok: false,
      configured: true,
      reason: 'fetch-failed',
      error: fetched.error,
      fetchedAt,
      provider,
      adapterName: adapter.name,
      status: 'stale',
      ...(failCapsuleHtml !== undefined ? { capsuleHtml: failCapsuleHtml } : {}),
    };
  }

  // 3. 落盘历史（按天分片 JSONL；失败不阻断展示，只记日志）
  const data = fetched.data ?? {};
  const capsInput = {
    time: fetchedAt,
    data,
    status: 'fresh' as const,
    esc,
  };

  // 4. safeFormat formatCapsule（宿主端渲染 HTML）+ 净化
  const formatted = await safeFormat(() => adapter.formatCapsule(capsInput), 'formatCapsule', ctx.timeoutMs);
  const capsuleHtml = formatted.html !== undefined ? sanitizeHtml(formatted.html) : undefined;

  return {
    ok: true,
    configured: true,
    reason: null,
    error: null,
    fetchedAt,
    provider,
    adapterName: adapter.name,
    status: 'fresh',
    capsuleHtml,
    rawData: data,
  };
}

/**
 * 从历史缓存路径返回胶囊内容（不重新拉取）。
 * 用于锁忙/降级场景。
 */
export async function capsuleHtmlFromHistory(
  history: HistoryStore,
  provider: string,
  adapterName: string,
  fallbackText: string,
): Promise<string | undefined> {
  const last = await history.last(provider, adapterName);
  if (last === null) return undefined;
  // 无 formatCapsule 时返回简单文本 HTML
  return `<span>${esc(fallbackText)}</span>`;
}

/** v2 面板管道：查询历史（全量）→ formatPanel → HTML。 */
export async function runV2PanelPipeline(opts: {
  adapter: UsageStatsAdapter;
  provider: string;
  history: HistoryStore;
  range: { start: number; end: number };
  timeoutMs?: number;
}): Promise<{ panelHtml?: string; error?: string }> {
  const { adapter, provider, history, range, timeoutMs = 2000 } = opts;
  const { entries } = await history.query(provider, adapter.name, range);
  const panelInput = {
    entries,
    range,
    truncated: false,
    esc,
  };
  const formatted = await safeFormat(() => adapter.formatPanel(panelInput), 'formatPanel', timeoutMs);
  if (formatted.error !== undefined) return { error: formatted.error };
  return { panelHtml: sanitizeHtml(formatted.html ?? '') };
}

// ------------------------------------------------------------------ #105① /history 渲染缓存（纯函数层）

/** 面板渲染缓存兜底 TTL：编译期常量，定界 [60s, 120s]（issue #105 正文①节）。
 *  仅作兜底而非主失效机制——主失效是 append 落盘全清；取区间中值 90s。 */
export const PANEL_CACHE_TTL_MS = 90000;

/** 面板渲染缓存条目：runV2PanelPipeline 返回值字符串层快照。
 *  绝不缓存 entries 中间层（formatPanel 是用户代码，可能变异入参）。 */
export interface PanelCacheEntry {
  panelHtml?: string;
  error?: string;
  at: number;
}

/** 自然日粒度归一化：时间戳折算到当地时区当日零点。
 *  路由的 end=Date.now() 每请求漂移，key 含精确时间戳会令缓存永不命中。 */
export function normalizeRangeDay(range: { start: number; end: number }): { start: number; end: number } {
  const dayFloor = (t: number): number => {
    const d = new Date(t);
    d.setHours(0, 0, 0, 0);
    return d.getTime();
  };
  return { start: dayFloor(range.start), end: dayFloor(range.end) };
}

/** 缓存 key = provider + adapterName + 归一化 range。
 *  不同 days 参数归一化到不同自然日窗口 → 不同 key，互不串数据。 */
export function panelCacheKey(
  provider: string,
  adapterName: string,
  range: { start: number; end: number },
): string {
  const n = normalizeRangeDay(range);
  return `${provider}\u0000${adapterName}\u0000${n.start}\u0000${n.end}`;
}

/** TTL 兜底过期判定（严格大于；now/entry.at 分离入参便于单测注入时钟）。 */
export function isPanelCacheStale(
  entry: Pick<PanelCacheEntry, "at">,
  now: number,
  ttlMs: number = PANEL_CACHE_TTL_MS,
): boolean {
  return now - entry.at > ttlMs;
}

