/**
 * dsh-provider-usage — HTML 结构化净化（XSS 兜底）。
 *
 * 信任模型：用户自己的 format 函数返回的 HTML 是信任域，但流入其中的
 * 外部 API 数据不可信。本模块在宿主端渲染前做白名单式净化，作为结构性兜底
 * （用户 format 函数还应使用 esc() 助手进行自家数据的转义）。
 *
 * #105③ 实体感知双层净化：
 * - 第一层：既有明文形态黑名单（行为不变）；
 * - 第二层：对第一层输出做**一轮** HTML 实体解码得到「检测副本」，协议类
 *   模式再经 WHATWG URL 语义剥除 \t\n\r 得二级视图，在视图上定位危险载体
 *   模式，命中后只从**原文**删除对应字节区间，迭代至收敛（宽松轮数上限 +
 *   触底 fail-closed，见 sanitizeHtml 第 4 步）。
 *   安全不变量（结构性保证）：
 *   1. 输出恒为输入的子序列（纯删除）——解码副本绝不回写为输出，
 *      因此 `&amp;#106;avascript:` / `&lt;script&gt;` 等本已安全的实体文本
 *      不可能被"误解码"升级为危险明文；
 *   2. 第二层迭代每轮要么无匹配终止、要么长度严格递减必终止；设宽松轮数
 *      上限（64，远超正常收敛所需）防最坏 O(n²) CPU 消耗（复核 P1-3），
 *      触底 fail-closed 丢弃输出返回 ''——f('')==='' 使幂等硬闸
 *      `sanitizeHtml(sanitizeHtml(x)) === sanitizeHtml(x)` 在任意分支构造
 *      成立，终态恒满足「解码 + URL 剥除后不含危险载体」。
 */

// ---------------------------------------------------------------- 第一层：明文形态黑名单

const SCRIPT_TAG_RE = /<script\b[^>]*>[\s\S]*?<\/script\s*>/giu;
const EVENT_HANDLER_RE = /\son\w+\s*=\s*(?:"[^"]*"|'[^']*'|[^\s>]+)/giu;
const IFRAME_RE = /<iframe\b[^>]*>[\s\S]*?<\/iframe\s*>/giu;
const FRAME_RE = /<frame\b[^>]*>[\s\S]*?<\/frame\s*>/giu;
const OBJECT_RE = /<object\b[^>]*>[\s\S]*?<\/object\s*>/giu;
const EMBED_RE = /<embed\b[^>]*>[\s\S]*?<\/embed\s*>/giu;
const META_RE = /<meta\b[^>]*>/giu;
const LINK_RE = /<link\b[^>]*>/giu;
const BASE_RE = /<base\b[^>]*>/giu;
const STYLE_ON_SCRIPT_RE = /expression\s*\(/giu;
const JAVASCRIPT_URI_RE = /\bjavascript\s*:/giu;
const DATA_TEXT_HTML_RE = /\bdata\s*:\s*text\/html/giu;

// ---------------------------------------------------------------- 第二层：实体感知

/**
 * 危险载体 token 级模式（在解码副本上匹配）。开/闭标签分开成对出现：
 * 实体化标签对（如 `&lt;script&gt;...&lt;/script&gt;`，浏览器渲染为纯文本）
 * 移除标签 token 后保留其间文本；真标签已在第一层整段移除。
 * 协议类模式除外——它们在 URL 剥除视图上匹配（见 URL_PROTOCOL_RES）。
 */
const DECODED_DANGER_RES: RegExp[] = [
  /<script\b[^>]*>/giu,
  /<\/script\s*>/giu,
  /<iframe\b[^>]*>/giu,
  /<\/iframe\s*>/giu,
  /<frame\b[^>]*>/giu,
  /<\/frame\s*>/giu,
  /<object\b[^>]*>/giu,
  /<\/object\s*>/giu,
  /<embed\b[^>]*>/giu,
  /<\/embed\s*>/giu,
  /<meta\b[^>]*>/giu,
  /<link\b[^>]*>/giu,
  /<base\b[^>]*>/giu,
  EVENT_HANDLER_RE,
  STYLE_ON_SCRIPT_RE,
];

/**
 * 协议类模式：WHATWG URL basic parser 在解析入口剥除输入中全部 ASCII
 * tab/newline/CR，故 `jav&#9;ascript:` 解码一轮得 `jav\tascript:` 后 scheme
 * 仍还原为 javascript:——此类载体必须在「解码 + 剥除」二级视图上定位
 * （PR#196 复核 P1-1）。
 */
const URL_PROTOCOL_RES: RegExp[] = [JAVASCRIPT_URI_RE, DATA_TEXT_HTML_RE];

const isUrlStrippedChar = (c: string) => c === "\t" || c === "\n" || c === "\r";

/**
 * 具名实体表：只收编「解码产物为 ASCII 且可能参与危险载体构造」的条目。
 * 全部键均为 WHATWG named character references 正式名的小写规范化形式
 * （已对照 https://html.spec.whatwg.org/entities.json 逐键核验，43/43 命中；
 * 小写存储 + 查询期 toLowerCase 即大小写不敏感匹配）。匹配分号可选——比
 * HTML5 更宽松属保守封堵方向；因解码副本只用于检测、不影响输出字节，宽松
 * 多解不会误伤合法内容。（HTML5 无产出单个 ASCII 字母的具名实体，字母拼接
 * 变体由数字实体路径覆盖。）
 */
const NAMED_ENTITIES: Record<string, string> = {
  lt: "<",
  gt: ">",
  amp: "&",
  quot: '"',
  apos: "'",
  colon: ":",
  semi: ";",
  equals: "=",
  sol: "/",
  bsol: "\\",
  num: "#",
  percnt: "%",
  quest: "?",
  excl: "!",
  commat: "@",
  lpar: "(",
  rpar: ")",
  lsqb: "[",
  lbrack: "[",
  rsqb: "]",
  rbrack: "]",
  lcub: "{",
  lbrace: "{",
  rcub: "}",
  rbrace: "}",
  lowbar: "_",
  underbar: "_",
  vert: "|",
  verbar: "|",
  verticalline: "|",
  period: ".",
  comma: ",",
  plus: "+",
  ast: "*",
  midast: "*",
  hat: "^",
  grave: "`",
  nbsp: "\u00a0",
  ensp: "\u2002",
  emsp: "\u2003",
  thinsp: "\u2009",
  tab: "\t",
  newline: "\n",
};

const isDigit = (c: string) => c >= "0" && c <= "9";
const isHexDigit = (c: string) => isDigit(c) || (c >= "a" && c <= "f") || (c >= "A" && c <= "F");
const isAlpha = (c: string) => (c >= "a" && c <= "z") || (c >= "A" && c <= "Z");
const isAlnum = (c: string) => isAlpha(c) || isDigit(c);

/** 一轮实体解码视图：decoded 每个 code unit 在原文中的 [start, end) 区间。 */
interface DecodedView {
  text: string;
  starts: number[];
  ends: number[];
}

/**
 * 对 html 做**恰好一轮**实体解码（模拟浏览器解析期行为），并记录每个
 * decoded code unit 的原文区间。解析规则刻意宽于 HTML5（保守封堵方向）：
 * - 数字实体：十进制/十六进制（x/X 前缀均可）、有无分号均解、前导零容忍；
 * - 具名实体：大小写不敏感、有无分号均解（qa 判据同款宽松语义）；
 * - 非法/未知形态按字面保留，不影响后续位置的独立解析。
 */
function decodeEntitiesOnce(html: string): DecodedView {
  const chars: string[] = [];
  const starts: number[] = [];
  const ends: number[] = [];
  const pushCu = (cu: string, s: number, e: number) => {
    chars.push(cu);
    starts.push(s);
    ends.push(e);
  };
  const n = html.length;
  let i = 0;
  while (i < n) {
    if (html[i] !== "&") {
      pushCu(html[i], i, i + 1);
      i++;
      continue;
    }
    const j = i + 1;
    // 数字实体 &#123; / &#x1F; / &#X1F;（分号可选）
    if (html[j] === "#") {
      const hex = html[j + 1] === "x" || html[j + 1] === "X";
      let k = j + (hex ? 2 : 1);
      const dStart = k;
      while (k < n && (hex ? isHexDigit(html[k]) : isDigit(html[k]))) k++;
      if (k > dStart) {
        const cp = parseInt(html.slice(dStart, k), hex ? 16 : 10);
        // HTML5 数值语义：0 / 代理区 / 超界映射 U+FFFD
        const safe =
          cp > 0 && cp <= 0x10ffff && !(cp >= 0xd800 && cp <= 0xdfff) ? cp : 0xfffd;
        let end = k;
        if (html[end] === ";") end++;
        for (const cu of String.fromCodePoint(safe)) pushCu(cu, i, end);
        i = end;
        continue;
      }
      pushCu("&", i, i + 1);
      i++;
      continue;
    }
    // 具名实体 &[a-zA-Z][a-zA-Z0-9]*（分号可选、大小写不敏感）
    if (isAlpha(html[j])) {
      let k = j + 1;
      while (k < n && isAlnum(html[k])) k++;
      const mapped = NAMED_ENTITIES[html.slice(j, k).toLowerCase()];
      if (mapped !== undefined) {
        let end = k;
        if (html[end] === ";") end++;
        pushCu(mapped, i, end);
        i = end;
        continue;
      }
    }
    pushCu("&", i, i + 1);
    i++;
  }
  return { text: chars.join(""), starts, ends };
}

/** 区间合并（按起点排序后吸收重叠/相邻）。 */
function mergeRanges(ranges: Array<[number, number]>): Array<[number, number]> {
  ranges.sort((a, b) => a[0] - b[0]);
  const merged: Array<[number, number]> = [];
  for (const r of ranges) {
    const last = merged[merged.length - 1];
    if (last !== undefined && r[0] <= last[1]) {
      last[1] = Math.max(last[1], r[1]);
    } else {
      merged.push([r[0], r[1]]);
    }
  }
  return merged;
}

/**
 * 单轮实体感知封闭：解码副本上收集全部危险 match，映射回原文一次性删除。
 * 协议类模式在「解码 + 剥除 \t\n\r」二级视图上定位（WHATWG URL 语义，
 * P1-1），match 区间经剥除下标 → 解码下标两跳映射回原文区间。
 */
function stripDecodedDanger(html: string): string {
  const view = decodeEntitiesOnce(html);
  // URL 剥除视图：view.text 去掉全部 \t\n\r，urlChars[k] = 剥除文本第 k 个
  // code unit 在 view.text（解码副本）中的下标
  const urlChars: number[] = [];
  let urlText = "";
  for (let i = 0; i < view.text.length; i++) {
    if (isUrlStrippedChar(view.text[i])) continue;
    urlText += view.text[i];
    urlChars.push(i);
  }
  const ranges: Array<[number, number]> = []; // 解码副本 code unit 下标区间 [s,e)
  for (const re of DECODED_DANGER_RES) {
    re.lastIndex = 0;
    for (const m of view.text.matchAll(re)) {
      ranges.push([m.index, m.index + m[0].length]);
    }
  }
  for (const re of URL_PROTOCOL_RES) {
    re.lastIndex = 0;
    for (const m of urlText.matchAll(re)) {
      // match 首尾字符映射回解码副本；夹在两者之间的被剥字符随连续原文区间一并覆盖
      let e = urlChars[m.index + m[0].length - 1] + 1;
      // 尾部吞掉紧邻的被剥字符（如 javascript:&#10;），不留孤儿实体碎片
      while (e < view.text.length && isUrlStrippedChar(view.text[e])) e++;
      ranges.push([urlChars[m.index], e]);
    }
  }
  if (ranges.length === 0) return html;
  // 两步合并非冗余：第一步合并解码层跨正则重叠；映射回原文后，多 code-unit
  // token（如 astral 实体的代理对）理论上可横跨两个相邻区间，故第二步做
  // 防御性合并（拆开嵌套双调调用以便阅读）
  const decodedCuts = mergeRanges(ranges);
  const cuts = mergeRanges(
    decodedCuts.map(([s, e]) => [view.starts[s], view.ends[e - 1]] as [number, number]),
  );
  let out = "";
  let pos = 0;
  for (const [s, e] of cuts) {
    out += html.slice(pos, s);
    pos = e;
  }
  return out + html.slice(pos);
}

/**
 * 白名单净化：移除脚本/事件处理器/危险元素，防御性净化用户 format HTML。
 *
 * 保持简单可靠（正则级）：我们的目标是移除 XSS 载体，而非完美 HTML 解析。
 * 后续如需更严格可换 DOMPurify（构建期 jsdom 不适用，保留正则方案）。
 */
export function sanitizeHtml(html: string): string {
  if (html === '') return '';
  // 1. 移除 script/frame/object/embed/meta/link/base 标签
  let out = html
    .replace(SCRIPT_TAG_RE, '')
    .replace(IFRAME_RE, '')
    .replace(FRAME_RE, '')
    .replace(OBJECT_RE, '')
    .replace(EMBED_RE, '')
    .replace(META_RE, '')
    .replace(LINK_RE, '')
    .replace(BASE_RE, '');
  // 2. 移除 on* 事件属性
  out = out.replace(EVENT_HANDLER_RE, '');
  // 3. 移除危险 URI 协议
  out = out
    .replace(JAVASCRIPT_URI_RE, '')
    .replace(DATA_TEXT_HTML_RE, '')
    .replace(STYLE_ON_SCRIPT_RE, '');
  // 4. 实体编码变体封闭（#105③）：迭代至收敛，设宽松轮数上限 + 触底 fail-closed。
  //    收敛性论证：stripDecodedDanger 要么无匹配原样返回（终止），要么至少
  //    删除一个非空 match 区间使长度严格递减——正常内容 1-3 轮收敛，
  //    深嵌套攻击构造（pad(25)）实测 ≤19 轮，上限 64 远超实际所需。
  //    上限的必要性（复核 P1-3）：无上限时「删除拼接出新匹配」类深嵌套
  //    构造最坏 O(n²)，60KB 输入实测冻结宿主事件循环 ~30s，且数据落盘
  //    history 后每次 /history 重复触发＝持续 DoS。
  //    触底 fail-closed：超限丢弃输出返回 ''。幂等与终态谓词同时保持——
  //    sanitizeHtml('') === ''（空串短路），故 f(f(x)) === f(x) 在超限分支
  //    构造成立，且 '' 显然满足「解码 + URL 剥除视图下不含危险载体」；
  //    攻击代价从 CPU 冻结退化为内容丢弃（fail-closed 方向）。
  let converged = false;
  for (let round = 0; round < 64; round++) {
    const next = stripDecodedDanger(out);
    if (next === out) {
      converged = true;
      break;
    }
    out = next;
  }
  return converged ? out : '';
}

packages/dsh-provider-usage/src/core/gua.source:
/**
 * dsh-provider-usage — 用户代码安全执行守卫。
 *
 * 纪律（用户明确要求）：
 * 1. 用户代码报错一定不能导致插件崩溃 —— 所有用户函数调用经本模块包装。
 * 2. 一定不能有阻塞/挂起的连接 —— 超时 + AbortSignal 传递，请求不挂起（取数超时固定 5s）。
 */

/**
 * 对用户 fetchData 的调用包装：强制超时（管线注入固定 5s）+ 信号合流下发 +
 * 序列化校验 + 错误隔离。
 *
 * 信号合流（issue #120 P0）：内部 AbortController 承担超时兜底；可选外部信号经
 * **手动级联监听**并入同一 controller（不用 AbortSignal.any——engines node>=20
 * 全系兼容），合并后的 signal 经 fn(signal) 下发给用户 fetchData。适配器把它
 * 透传给底层 fetch 的 RequestInit.signal 即可在超时/外部取消时真正中断请求，
 * 不再悬挂 socket；0 参声明的 fetchData 忽略入参，完全向后兼容。
 *
 * @param fn 用户 fetchData（入参为合并信号；0 参调用兼容）
 * @param timeoutMs 超时毫秒（生产管线恒传 fetchTimeoutMs=5000；签名默认值仅兜底）
 * @param externalSignal 可选外部取消信号（如宿主请求断连），abort 时立即取消取数
 * @returns 成功返回 { data }；失败返回 { error }（绝不抛异常）。
 */
export async function safeFetchData(
  fn: (signal: AbortSignal) => Promise<unknown>,
  timeoutMs = 2000,
  externalSignal?: AbortSignal,
): Promise<{ data?: Record<string, unknown>; error?: string }> {
  // 已 abort 的外部信号：入口同步短路（不建 controller、不发起 fn），
  // 避免「abort 早于 race 监听器注册」的事件错失悬挂
  if (externalSignal !== undefined && externalSignal.aborted) {
    return { error: 'fetchData 已被取消' };
  }
  const controller = new AbortController();
  let done = false;
  let timedOut = false;
  // 手动级联监听：外部信号 abort → 内部 controller 同步 abort（合并语义）；
  // finally 中摘除监听，防止长生命周期外部信号累积监听器泄漏。
  const cascadeAbort = (): void => {
    if (!done) controller.abort();
  };
  if (externalSignal !== undefined) {
    externalSignal.addEventListener('abort', cascadeAbort, { once: true });
  }
  const timer = setTimeout(() => {
    if (!done) {
      timedOut = true;
      controller.abort();
    }
  }, timeoutMs);
  try {
    // 合并信号下发给用户 fetchData：超时兜底与外部取消共用同一 signal，
    // 底层 fetch 收到 abort 后中断真实请求（超时文案稳定为「fetchData 超时」）
    const userP = Promise.resolve().then(() => fn(controller.signal));
    // #120 接线配套：信号透传后，超时/外部取消判负的用户 promise 会随后收到
    // abort 拒绝——挂一个空 catch 防 unhandled rejection（错误仍经下方 catch 上报）
    userP.catch(() => {});
    const raw = await Promise.race([
      userP,
      new Promise<never>((_, reject) => {
        controller.signal.addEventListener('abort', () => {
          reject(new Error(timedOut ? 'fetchData 超时' : 'fetchData 已被取消'));
        }, { once: true });
      }),
    ]);
    // 序列化校验：确保可写入 JSONL / 下发客户端
    const json = JSON.stringify(raw);
    const parsed: unknown = JSON.parse(json);
    if (typeof parsed !== 'object' || parsed === null || Array.isArray(parsed)) {
      return { error: 'fetchData 必须返回对象' };
    }
    return { data: parsed as Record<string, unknown> };
  } catch (e: unknown) {
    const msg = e instanceof Error ? e.message : String(e);
    return { error: msg };
  } finally {
    done = true;
    clearTimeout(timer);
    // 摘除外部信号上的级联监听（取数已结束，后续外部 abort 与本次调用无关）
    if (externalSignal !== undefined) {
      externalSignal.removeEventListener('abort', cascadeAbort);
    }
  }
}

/**
 * 对用户 formatCapsule/formatPanel 的调用包装：超时由调用方注入 + 返回值类型校验。
 *
 * 注意：format 函数通常是同步的。同步死循环无法被真超时中断（JS 单线程），
 * 本包装的超时只对异步 format 生效；同步死循环由调用方文档化风险。
 */
export async function safeFormat(
  fn: () => string,
  name: string,
  timeoutMs = 2000,
): Promise<{ html?: string; error?: string }> {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), timeoutMs);
  try {
    const html = await Promise.race([
      Promise.resolve().then(fn),
      new Promise<never>((_, reject) => {
        controller.signal.addEventListener('abort', () => {
          reject(new Error(`${name} 超时`));
        }, { once: true });
      }),
    ]);
    if (typeof html !== 'string') return { error: `${name} 必须返回字符串` };
    return { html };
  } catch (e: unknown) {
    return { error: e instanceof Error ? e.message : String(e) };
  } finally {
    clearTimeout(timer);
  }
}

/**
 * 带超时的 fetch（AbortController 实现），用于客户端轮询等场景。
 * 超时后 abort 请求，不挂起连接。
 */
export async function fetchWithTimeout(
  url: string,
  timeoutMs = 10000,
  init: RequestInit = {},
): Promise<Response> {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), timeoutMs);
  try {
    return await fetch(url, { ...init, signal: controller.signal });
  } finally {
    clearTimeout(timer);
  }
}

