// ---------------------------------------------------------------- 6) HotReloadableAdapter onReload 回调全分支

// 6a) 合法用户适配器文件 → onReload ok:true → hr.current !== null → full branch
{
  const dir = mkdtempSync(join(tmpdir(), "dou-hr-"));
