  const svg = miniChartSvgMarkup({
    samples: [{ x: T0, y: 10 }, { x: T0 + 30 * MIN, y: 20 }],
    color: "#abc", lo: 0, hi: 100,
    resetsAt: new Date(T0 + 35 * MIN).toISOString(),
    resetPeriodMs: 10 * MIN, dateOnly: false,
  });
